typedef unsigned int u_int;
typedef unsigned short u_short;
typedef unsigned char u_char;

enum
{
  NGLTEX_TGA,
  NGLTF_32BIT = 0x1,
  NGLTF_16BIT = 0x2,
  NGLTF_TEMP = 0x1000,
  NGLTF_RENDER_TARGET = 0x2000,
  NGLTF_VRAM_ONLY = 0x8000,
  SCE_GS_PSMCT32 = 0,
  SCE_GS_PSMCT16 = 2
};

struct nglTexture
{
  char _pad0[8];
  u_short Width, Height;
  u_int _padC;
  u_char Type, TW, TH, _pad13;
  struct
  {
    u_int LoadedInPlace : 1;
    u_int Locked : 1;
    u_int VRAMOnly : 1;
    u_int System : 1;
    u_int RenderTarget : 1;
  } Flags;
  u_int _ph;
  u_int Format;
  u_int* Data;
  char _pad24[8];
  u_int SrcDataSize;
  char _pad30[52];
  u_int GsSize;
  char _pad68[200];
};

void* nglListAlloc( u_int Bytes, u_int Alignment = 4 );
#define nglListNew( Type ) (Type*)nglListAlloc( sizeof(Type) )
void* nglMemAlloc( u_int Size, u_int Align = 1 );
void nglMemFree( void* Ptr );
void nglWarning( const char* Format, ... );
void nglCalcTextureGSRegs( nglTexture* Tex );
extern "C" void* memset( void* Dest, int Value, u_int Size );
#define NULL 0

nglTexture* nglCreateTexture( u_int Format, u_int Width, u_int Height )
{
  nglTexture* Tex;
  if ( Format & NGLTF_TEMP )
    Tex = nglListNew( nglTexture );
  else
    Tex = (nglTexture*)nglMemAlloc( sizeof(nglTexture) );
  if ( !Tex )
    return NULL;

  memset( Tex, 0, sizeof(nglTexture) );

  Tex->Type = NGLTEX_TGA;

  u_int PixelSize = 0;
  if ( ( Format & 0xFF ) == NGLTF_32BIT )
  {
    Tex->Format = SCE_GS_PSMCT32;
    PixelSize = 4;
  }
  else
  if ( ( Format & 0xFF ) == NGLTF_16BIT )
  {
    Tex->Format = SCE_GS_PSMCT16;
    PixelSize = 2;
  }
  else
  {
    nglWarning( "NGL: Tried to create a texture without a valid format.\n" );
    return NULL;
  }

  Tex->Width = Width;
  Tex->Height = Height;

  if ( Format & NGLTF_VRAM_ONLY )
    Tex->Flags.VRAMOnly = 1;
  else
  if ( !( Format & NGLTF_TEMP ) )
  {
    Tex->Data = (u_int*)nglMemAlloc( Tex->Width * Tex->Height * PixelSize );
    if ( !Tex->Data )
    {
      nglMemFree( Tex );
      return NULL;
    }
  }

  if ( Format & NGLTF_RENDER_TARGET )
    Tex->Flags.RenderTarget = 1;

  // Calculate GS storage requirement.
  Tex->GsSize = ( ( Tex->Width * Tex->Height * PixelSize / 256 ) + 31 ) & ~31;
  Tex->SrcDataSize = Tex->Width * Tex->Height * PixelSize;

  nglCalcTextureGSRegs( Tex );

  return Tex;
}
